KG42.register("rules-80d2dc5d069e35bb57bdd8d6",{"id":"27-multiple_microgrid_trading::v141-c-R006","paper":"27-multiple_microgrid_trading","record":{"rule_id":"v141-c-R006","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"At each microgrid, generated energy plus energy purchased through incoming connections must equal consumed energy plus energy sold through outgoing connections. Scope: Energy exchanges among the interconnected islanded microgrids during each scheduling interval. The energy exchanged from μG-i to μG-j must be zero: E_{i,j}=0 MWh. Scope: Directed energy exchanges between microgrid pairs in the modeled network. Condition: a_{i,j}=0, meaning there is no connection from μG-i to μG-j. The connection topology may permit energy exchange between microgrids in only one direction. Scope: Permitted directions of energy exchange in the arbitrary microgrid connection topology. Every directed energy-exchange quantity E_{i,j} must be nonnegative. Scope: Directed energy-exchange quantities in the cooperative system equilibrium defined by problem (3).","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Directed energy exchanges between microgrid pairs in the modeled network. | Directed energy-exchange quantities in the cooperative system equilibrium defined by problem (3). | Energy exchanges among the interconnected islanded microgrids during each scheduling interval. | Permitted directions of energy exchange in the arbitrary microgrid connection topology.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006","v141-b-g08-e008","v141-b-g09-e009"]},"x":[{"variable_id":"v141-c-R006-X001","symbol":"E_{i,j}","meaning":"Directed energy quantity sold/exchanged from microgrid μG-i to microgrid μG-j during the scheduling interval.","kind":"operational","domain":"Nonnegative energy quantity in MWh for i,j=1,...,M; forced to zero when a_{i,j}=0.","unit":"MWh","indices":["i","j"],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006","v141-b-g09-e009"]},{"variable_id":"v141-c-R006-X002","symbol":"E_i^{(g)}","meaning":"Energy generated by microgrid μG-i during the scheduling interval.","kind":"operational","domain":"Energy quantity in MWh generated by μG-i; the quoted definition does not state an explicit sign bound.","unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g04-e004","v141-b-g09-e009"]},{"variable_id":"v141-c-R006-X003","symbol":"E_i^{(b)}","meaning":"M-dimensional column vector E_i^{(b)}=[E_{1,i} ... E_{M,i}]^T gathering the energy quantities bought by μG-i from each μG.","kind":"operational","domain":"M-dimensional column vector of bought-energy quantities; entries are the directed quantities E_{j,i}, which are nonnegative in problem (3).","unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g06-e006"]},{"variable_id":"v141-c-R006-X004","symbol":"E_i^{(s)}","meaning":"M-dimensional column vector E_i^{(s)}=[E_{i,1} ... E_{i,M}]^T gathering the energy quantities sold by μG-i to each μG.","kind":"operational","domain":"M-dimensional column vector of sold-energy quantities; entries are the directed quantities E_{i,j}, which are nonnegative in problem (3).","unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g06-e006"]}],"theta":[{"parameter_id":"v141-c-R006-T001","symbol":"M","meaning":"Number of interconnected microgrids (μGs) operating in islanded mode.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g04-e004"]},{"parameter_id":"v141-c-R006-T002","symbol":"E_i^{(c)}","meaning":"Energy consumed by microgrid μG-i during the scheduling interval (local load).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g04-e004"]},{"parameter_id":"v141-c-R006-T003","symbol":"A","meaning":"M×M adjacency matrix A=[a_{i,j}]_{M×M} whose entry is 1 if a directed connection from μG-i to μG-j exists and 0 otherwise; A may be nonsymmetric.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g06-e006"]},{"parameter_id":"v141-c-R006-T004","symbol":"a_{i,j}","meaning":"Binary directed-connection indicator: 1 if there is a connection from μG-i to μG-j, and 0 otherwise; diagonal entries are fixed to 0.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","j"],"evidence_ids":["v141-b-g06-e006"]},{"parameter_id":"v141-c-R006-T005","symbol":"e_i","meaning":"i-th column of the M×M identity matrix, used to select the i-th component of a vector.","value":{"kind":"symbolic","number_value":null,"text_value":"i-th column of the M×M identity matrix"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g10-e010"]}],"phi":[{"constraint_id":"v141-c-R006-C001","kind":"mathematical","role":"core","statement":"At each microgrid, generated energy plus energy purchased through incoming connections must equal consumed energy plus energy sold through outgoing connections. Scope: Energy exchanges among the interconnected islanded microgrids during each scheduling interval.","expression":"E_i^{(g)} + e_i^T A^T E_i^{(b)} = E_i^{(c)} + e_i^T A E_i^{(s)} \\quad \\forall i\\in\\{1,\\ldots,M\\}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X002","v141-c-R006-X003","v141-c-R006-X004"],"parameter_refs":["v141-c-R006-T001","v141-c-R006-T002","v141-c-R006-T003","v141-c-R006-T005"],"evidence_ids":["v141-b-g04-e004","v141-b-g06-e006","v141-b-g05-e005","v141-b-g10-e010"]},{"constraint_id":"v141-c-R006-C002","kind":"mathematical","role":"core","statement":"The energy exchanged from μG-i to μG-j must be zero: E_{i,j}=0 MWh. Scope: Directed energy exchanges between microgrid pairs in the modeled network. Condition: a_{i,j}=0, meaning there is no connection from μG-i to μG-j.","expression":"a_{i,j}=0 \\;\\Rightarrow\\; E_{i,j}=0\\ \\text{MWh} \\quad \\forall i,j\\in\\{1,\\ldots,M\\}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X001"],"parameter_refs":["v141-c-R006-T001","v141-c-R006-T004"],"evidence_ids":["v141-b-g06-e006"]},{"constraint_id":"v141-c-R006-C003","kind":"procedural","role":"core","statement":"The connection topology may permit energy exchange between microgrids in only one direction. Scope: Permitted directions of energy exchange in the arbitrary microgrid connection topology.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g06-e006"]},{"constraint_id":"v141-c-R006-C004","kind":"mathematical","role":"core","statement":"Every directed energy-exchange quantity E_{i,j} must be nonnegative. Scope: Directed energy-exchange quantities in the cooperative system equilibrium defined by problem (3).","expression":"E_{i,j}\\ge 0 \\quad \\forall i,j\\in\\{1,\\ldots,M\\}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R006-X001"],"parameter_refs":["v141-c-R006-T001"],"evidence_ids":["v141-b-g08-e008","v141-b-g09-e009"]},{"constraint_id":"v141-c-R006-C005","kind":"mathematical","role":"supporting","statement":"By convention, the adjacency matrix has zero diagonal: a_{i,i}=0 for all i=1,...,M. Scope: Directed connection topology in the system model.","expression":"a_{i,i}=0 \\quad \\forall i\\in\\{1,\\ldots,M\\}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":["v141-c-R006-T001","v141-c-R006-T004"],"evidence_ids":["v141-b-g06-e006"]}],"pi":[{"evidence_id":"v141-b-g04-e004","location":{"location_id":"src-f5dd785b87-p02-c2r1__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"IEEE TRANSACTIONS ON INDUSTRIAL ELECTRONICS, VOL. 62, NO. 4, APRIL 2015 we from an economical point ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Consider a system composed of M interconnected microgrids (μGs) operating in islanded mode. During each scheduling interval, each microgrid μG-i generates E_i^{(g)} units of energy and consumes E_i^{(c)} units of energy. Moreover, μG-i may be allowed to sell energy E_{i,j} to μG-j, j≠i, and to buy energy E_{k,i} from μG-k, k≠i. Then, the energy equilibrium within the μG requires E_i^{(g)} + e_i^T A^T E_i^{(b)} = E_i^{(c)} + e_i^T A E_i^{(s)} (1)"},{"evidence_id":"v141-b-g06-e006","location":{"location_id":"src-f5dd785b87-p02-c2r2__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"to sell energy Ei,j to μG j, j̸ i, and to buy energy Ek,i fromrgy μG-k, k̸=i. Then, the energy equil","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"where the two M-dimensional column vectors, i.e., E_i^{(b)} = [E_{1,i} ... E_{M,i}]^T, E_i^{(s)} = [E_{i,1} ... E_{i,M}]^T (2) gather all the energy quantities bought and sold, respectively, by μG-i. In addition, we have introduced adjacency matrix A = [a_{i,j}]_{M×M}, where element a_{i,j} is equal to 1 if there exists a connection from μG-i to μG-j and 0 otherwise. Note that, generally, A may be nonsymmetric, meaning that at least two μGs are allowed to exchange energy in one direction only. By convention, we fix a_{i,i}=0. Moreover, a_{i,j}=0 ⇒ E_{i,j}=0 MWh for all i,j=1,...,M."},{"evidence_id":"v141-b-g08-e008","location":{"location_id":"src-f5dd785b87-p02-c2r4__v141-a-M01-clearing","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"ra- Finally, we further assume that all μGs agree to cooperate gly, with one another in order to min","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"Finally, we further assume that all μGs agree to cooperate with one another in order to minimize the total cost of the system. In other words, the energy quantities exchanged by the interconnected μGs form the equilibrium point of the following minimization problem:"},{"evidence_id":"v141-b-g09-e009","location":{"location_id":"src-f5dd785b87-p02-c2r4__v141-a-M01-clearing","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"ra- Finally, we further assume that all μGs agree to cooperate gly, with one another in order to min","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"C^* = min_{ {E_{i,j}} } ∑_{i=1}^M C_i(E_i^{(c)} + e_i^T A E_i^{(s)} - A^T E_i^{(b)}) + ∑_{i=1}^M e_i^T A^T γ(E_i^{(b)}) s.t. E_{i,j} ≥ 0 ∀i,j, E_i^{(c)} + e_i^T A E_i^{(s)} - A^T E_i^{(b)} ≥ 0 ∀i (3)"},{"evidence_id":"v141-b-g05-e005","location":{"location_id":"src-f5dd785b87-p02-c2r1__v141-a-M01-clearing","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"IEEE TRANSACTIONS ON INDUSTRIAL ELECTRONICS, VOL. 62, NO. 4, APRIL 2015 we from an economical point ","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"E_i^{(g)} + e_i^T A^T E_i^{(b)} = E_i^{(c)} + e_i^T A E_i^{(s)} (1)"},{"evidence_id":"v141-b-g10-e010","location":{"location_id":"src-f5dd785b87-p03-c1r1__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"GREGORATTI AND MATAMOROS: DISTRIBUTED ENERGY TRADING: MULTIPLE-MIC where ei is the ith column of the","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"where e_i is the ith column of the M×M identity matrix and, with some abuse of notation, we wrote γ(E_i^{(b)})=[γ(E_{1,i}) ... γ(E_{M,i})]^T. In addition, we used (1) to get rid of variables {E_i^{(g)}}. Note that problem (3) considers the μGs as parts of a common system (for instance, they are controlled by the same operator), and the aim is at minimizing the global cost, without focusing on the benefits/losses of each individual μG. We will see later on, however, that the proposed distributed and iterative minimization algorithm opens to a wider sense interpretation, where achieving the global objective implies a cost reduction at every μG."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g04-e004","quote":"Then, the energy equilibrium within the μG requires E_i^{(g)} + e_i^T A^T E_i^{(b)} = E_i^{(c)} + e_i^T A E_i^{(s)} (1)"},{"evidence_id":"v141-b-g06-e006","quote":"where the two M-dimensional column vectors, i.e., E_i^{(b)} = [E_{1,i} ... E_{M,i}]^T, E_i^{(s)} = [E_{i,1} ... E_{i,M}]^T (2) gather all the energy quantities bought and sold, respectively, by μG-i."}],[{"evidence_id":"v141-b-g06-e006","quote":"where element a_{i,j} is equal to 1 if there exists a connection from μG-i to μG-j and 0 otherwise."},{"evidence_id":"v141-b-g06-e006","quote":"Moreover, a_{i,j}=0 ⇒ E_{i,j}=0 MWh for all i,j=1,...,M."}],[{"evidence_id":"v141-b-g06-e006","quote":"Note that, generally, A may be nonsymmetric, meaning that at least two μGs are allowed to exchange energy in one direction only."}],[{"evidence_id":"v141-b-g08-e008","quote":"the energy quantities exchanged by the interconnected μGs form the equilibrium point of the following minimization problem:"},{"evidence_id":"v141-b-g09-e009","quote":"s.t. E_{i,j} ≥ 0 ∀i,j"}]],"C2_formalization":{"graph_sha256":"a7f9e2c024aaadbee4b7f28e04aa28acb0c31496d52c01fec3b8c7d41e15518e","applicability":"formalized","reason":"C001, C002, and C004 are directly supported by source equation (1), the adjacency implication, and the nonnegativity constraint in problem (3). C005 records the source's fixed zero diagonal of the adjacency matrix. C003 remains a qualitative topology permission and is left not_formalized. B evidence remains unreviewed under the experiment policy.","bindings":[{"object_id":"v141-c-R006-X001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Directed trade quantity E_{i,j} is the energy-exchange object governed by the approved execution.energy_trade function; the frozen graph has no edge for this unary trade fact."},{"object_id":"v141-c-R006-X002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Generation quantity appears in the local energy-balance equation (1) for the energy-trade execution node."},{"object_id":"v141-c-R006-X003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Bought-energy vector is used in balance equation (1) and is attached to execution.energy_trade."},{"object_id":"v141-c-R006-X004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Sold-energy vector is used in balance equation (1) and is attached to execution.energy_trade."},{"object_id":"v141-c-R006-T001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"M defines the microgrid index range used by the energy-trade execution statement."},{"object_id":"v141-c-R006-T002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Local consumption E_i^{(c)} is the fixed load input in the energy-balance equation for the execution node."},{"object_id":"v141-c-R006-T003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Adjacency matrix A parameterizes which directed energy exchanges are permitted for execution.energy_trade."},{"object_id":"v141-c-R006-T004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The entry a_{i,j} is the directed-connection indicator used in the zero-trade implication for execution.energy_trade."},{"object_id":"v141-c-R006-T005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Identity-column selector e_i is used in equation (1) to express aggregate bought and sold energy for execution.energy_trade."},{"object_id":"v141-c-R006-C001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formal transcription of source equation (1) for the sole frozen node execution.energy_trade; no graph edge is needed for this unary balance condition."},{"object_id":"v141-c-R006-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formal transcription of the source implication a_{i,j}=0 ⇒ E_{i,j}=0 for directed energy exchange; attached to execution.energy_trade."},{"object_id":"v141-c-R006-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formal transcription of the nonnegativity constraint E_{i,j}≥0 in problem (3); attached to execution.energy_trade."},{"object_id":"v141-c-R006-C005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formal transcription of the source convention a_{i,i}=0, supporting the directed trade topology under execution.energy_trade."}],"revision_requests":[]}},"quarantined_references":[]}});
